<?php if ( ! defined('BASEPATH')) exit('No direct script access allowed');class Commonadmin extends CI_Controller {	private $limit = 1;	public function __construct() {        parent::__construct();		error_reporting(0);		$this->load->helper('cookie');		$this->load->helper('xssclean');		$this->load->library('email');		$this->load->helper('email');		$this->load->helper('common');	}	function downloadfile() {		$VarFilePath										    = base64_decode(urldecode($this->uri->segment(4)));		fnDownloadFile($VarFilePath);		die;	}    public function addeditcadrequirement() {        $ArrData = array('ArrBasicInfo' => array(), 'VarId' => '', 'VarNew' => 0);        $VarTd = base64_decode(urldecode($this->uri->segment(4)));        if ($VarTd >= 1) {            $ArrResults = $this->mcadmodel->fnGetcadrequirementInfo('', '', $VarTd,'1');            $ArrData['ArrBasicInfo'] = $ArrResults[0];            $ArrData['VarId'] = $ArrResults[0]['id'];        } else {            $ArrData['VarNew'] = 1;        }        $this->load->view(CNFCOMPANY . 'addeditcadrequirement', $ArrData);    }    public function updatecadrequirementinfo() {        $ArrResult = array();        $VarCadReq = xssclean($this->input->post('r'));        $VarStatus = xssclean($this->input->post('s'));        $VarId = xssclean($this->input->post('id'));        if ($VarCadReq <> '') {            $ArrUpdateData = array('id' => $VarId, 'requirement' => $VarCadReq,'type'=>'1', 'companyid' => $this->companyid, 'status' => $VarStatus, 'updatedby' => $this->userid, 'dateupdated' => date('Y-m-d H:i:s'));            if ($VarId == '' || $VarId == 0) {                $ArrUpdateData['datecreated'] = date('Y-m-d H:i:s');            }            $ArrStatus = $this->mcadmodel->savecadrequirementInfo($ArrUpdateData);            echo json_encode($ArrStatus);            unset($ArrStatus);            unset($ArrUpdateData);            die;        } else {            $ArrResult['errcode'] = '-1';            $ArrResult['msg'] = 'Invalid Input!';        }        echo json_encode($ArrResult);    }    public function managecadrequirement() {        $VarFrom         = xssclean($this->input->post('rfrom'));        $VarRequirement  = xssclean($this->input->post('r'));        $VarStatus       = xssclean($this->input->post('s'));        $clickedColumnId = xssclean($this->input->post('columnId'));        $newsortorder    = xssclean($this->input->post('sortorder'));        $VarAfilter      = xssclean($this->input->post('afilter'));        $ArrDbCols       = array('c.requirement', 'c.dateupdated', 'c.status', 'u.contactname');        if ($VarFrom == 1) {            $VarURLSegment = 4;            $this->load->library('pagination');            $config['base_url']    = base_url() . CNFCOMPANY . 'mcadrequirement/managecadrequirement/';            $config['total_rows']  = $this->mcadmodel->fnCountRequirement($VarRequirement, $VarStatus, $VarAfilter);            $config['per_page']    = $this->limit;            $config['uri_segment'] = $VarURLSegment;            $offset                = $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby    = "dateupdated";            $sortorder = "desc";            if ($clickedColumnId <> '' && $newsortorder <> '') {                if (array_key_exists($clickedColumnId, $ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrFabricTypeList = $this->mcadmodel->fnListCadRequirement($VarRequirement, $VarStatus, $this->limit, $offset, $sortby, $sortorder, $VarAfilter)->result();            $data['pagination'] = $this->pagination->create_linkswithajax('Requirement');            $i                  = 0;            $ArrFnlList         = array();            $ArrStatus          = unserialize(ARRSTATUS);            foreach ($ArrFabricTypeList as $ObjFabric) {                $ArrFnlList[$i]['id'] = $ObjFabric->id;                $ArrFnlList[$i]['req']  = $ObjFabric->requirement;                $ArrFnlList[$i]['s']  = $ArrStatus[$ObjFabric->status];                $ArrFnlList[$i]['u']  = $ObjFabric->contactname;                $ArrFnlList[$i]['du'] = date('d-m-Y H:i:s', strtotime($ObjFabric->dateupdated));                $i                    = $i + 1;            }            echo json_encode(array('errcode' => 1, 'cn' => $config['total_rows'], 'ct' => $i, 're' => $ArrFnlList, 'pa' => base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY . 'managecadrequirement');        }    }    function changemStatus() {        $VarActDeactOption = xssclean($this->input->post('actdeactFabType'));        $VarCid = xssclean($this->input->post('cid'));        if ($VarActDeactOption <> '' && $VarCid <> '') {            $this->mcadmodel->fnChangeCadrequirementStat($VarCid, $VarActDeactOption);        }        echo json_encode(array('errcode' => 1));        die;    }    function delInfo() {        $VarCadRequirementId = xssclean($this->input->post('id'));        $VarUpdatedBy = $this->userid;        if ($VarCadRequirementId >= 1) {            $ArrResult = $this->mcadmodel->fnDelCadRequirement($VarCadRequirementId, $VarUpdatedBy);        } else {            $ArrResult['errcode'] = -1;            $ArrResult['msg'] = '';        }        echo json_encode($ArrResult);    }    /******************** PURPOSE (set type- 2) ********************************/    public function addeditcadpurpose() {        $ArrData = array('ArrBasicInfo' => array(), 'VarId' => '', 'VarNew' => 0);        $VarTd = base64_decode(urldecode($this->uri->segment(4)));        if ($VarTd >= 1) {            $ArrResults = $this->mcadmodel->fnGetcadpurposeinfo('', '', $VarTd,'2');            $ArrData['ArrBasicInfo'] = $ArrResults[0];            $ArrData['VarId'] = $ArrResults[0]['id'];        } else {            $ArrData['VarNew'] = 1;        }        $this->load->view(CNFCOMPANY . 'addeditcadpurpose', $ArrData);    }    public function managecadpurpose() {        $VarFrom         = xssclean($this->input->post('rfrom'));        $VarPurpose      = xssclean($this->input->post('p'));        $VarStatus       = xssclean($this->input->post('s'));        $clickedColumnId = xssclean($this->input->post('columnId'));        $newsortorder    = xssclean($this->input->post('sortorder'));        $VarAfilter      = xssclean($this->input->post('afilter'));        $VarType      = '2';        $ArrDbCols       = array('c.purpose', 'c.dateupdated', 'c.status', 'u.contactname');        if ($VarFrom == 1) {            $VarURLSegment = 4;            $this->load->library('pagination');            $config['base_url']    = base_url() . CNFCOMPANY . 'mcadrequirement/managecadpurpose/';            $config['total_rows']  = $this->mcadmodel->fnCountPurpose($VarPurpose, $VarStatus,$VarType, $VarAfilter);            $config['per_page']    = $this->limit;            $config['uri_segment'] = $VarURLSegment;            $offset                = $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby    = "dateupdated";            $sortorder = "desc";            if ($clickedColumnId <> '' && $newsortorder <> '') {                if (array_key_exists($clickedColumnId, $ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrFabricTypeList = $this->mcadmodel->fnListCadPurpose($VarPurpose, $VarStatus, $VarType,$this->limit, $offset, $sortby, $sortorder, $VarAfilter)->result();            $data['pagination'] = $this->pagination->create_linkswithajax('Requirement');            $i                  = 0;            $ArrFnlList         = array();            $ArrStatus          = unserialize(ARRSTATUS);            foreach ($ArrFabricTypeList as $ObjFabric) {                $ArrFnlList[$i]['id'] = $ObjFabric->id;                $ArrFnlList[$i]['p']  = $ObjFabric->purpose;                $ArrFnlList[$i]['s']  = $ArrStatus[$ObjFabric->status];                $ArrFnlList[$i]['u']  = $ObjFabric->contactname;                $ArrFnlList[$i]['du'] = date('d-m-Y H:i:s', strtotime($ObjFabric->dateupdated));                $i                    = $i + 1;            }            echo json_encode(array('errcode' => 1, 'cn' => $config['total_rows'], 'ct' => $i, 're' => $ArrFnlList, 'pa' => base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY . 'managecadpurpose');        }    }    function updatecadpurposeinfo() {        $ArrResult = array();        $VarCadPurpose = xssclean($this->input->post('p'));        $VarStatus = xssclean($this->input->post('s'));        $VarId = xssclean($this->input->post('id'));        if ($VarCadPurpose <> '') {            $ArrUpdateData = array('id' => $VarId, 'purpose' => $VarCadPurpose,'type'=>'2', 'companyid' => $this->companyid, 'status' => $VarStatus, 'updatedby' => $this->userid, 'dateupdated' => date('Y-m-d H:i:s'));            if ($VarId == '' || $VarId == 0) {                $ArrUpdateData['datecreated'] = date('Y-m-d H:i:s');            }            $ArrStatus = $this->mcadmodel->savecadpurposeInfo($ArrUpdateData);            echo json_encode($ArrStatus);            unset($ArrStatus);            unset($ArrUpdateData);            die;        } else {            $ArrResult['errcode'] = '-1';            $ArrResult['msg'] = 'Invalid Input!';        }        echo json_encode($ArrResult);    }    function delcadpurposeinfo() {        $VarCadRequirementId = xssclean($this->input->post('id'));        $VarUpdatedBy = $this->userid;        if ($VarCadRequirementId >= 1) {            $ArrResult = $this->mcadmodel->fnDelCadPurpose($VarCadRequirementId, $VarUpdatedBy);        } else {            $ArrResult['errcode'] = -1;            $ArrResult['msg'] = '';        }        echo json_encode($ArrResult);    }}